_DIG = "oh one two three four five six seven eight nine".split()

def _room_code(m):
    # Reina Sofia room codes: "205.10" -> "two-oh-five point ten", "201.03" -> "two-oh-one point three"
    a, b = m.group(1), m.group(2)
    return "-".join(_DIG[int(c)] for c in a) + " point " + str(int(b))

def apply_respelling(text, enable=True):
    if not enable:
        return text
    text = re.sub(r'\b([1-4]0[0-9])\.([0-9]{2})\b', _room_code, text)
    for name in sorted(PRONUNCIATION, key=len, reverse=True):
        text = re.sub(r'\b' + re.escape(name) + r'\b', PRONUNCIATION[name], text)
    return text
